<style>.wf-hero{display:flex;justify-content:space-between;gap:24px;align-items:end;padding:34px;border:1px solid #3a301d;background:radial-gradient(circle at 90% 0,#33270d 0,transparent 35%),linear-gradient(145deg,#171717,#090909);border-radius:18px}.wf-hero small{color:#cba64a;letter-spacing:.2em}.wf-hero h2{font:400 clamp(34px,5vw,64px)/1.02 Georgia,serif;margin:12px 0}.wf-hero em{color:#d4af37;font-weight:400}.wf-hero p{color:#999;max-width:680px}.wf-pulse,.wf-status{border:1px solid #574720;color:#e1bd59;border-radius:99px;padding:7px 10px;font-size:10px;letter-spacing:.1em;white-space:nowrap}.wf-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0}.wf-metrics article,.wf-panel{min-width:0;border:1px solid #30291b;background:#101010;border-radius:14px;padding:18px}.wf-metrics span{color:#888}.wf-metrics strong{display:block;color:#d4af37;font:400 36px Georgia,serif;margin-top:8px}.wf-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,1fr);gap:18px}.wf-heading,.wf-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.wf-heading a,.wf-table a{color:#d4af37}.wf-table{max-width:100%;overflow-x:auto}.wf-table table{width:100%;min-width:680px;border-collapse:collapse}.wf-table th,.wf-table td{text-align:left;padding:13px;border-bottom:1px solid #292929}.wf-table th{color:#777;font-size:11px;text-transform:uppercase}.wf-empty{color:#777;padding:30px!important}.wf-list{color:#aaa;line-height:2}.wf-btn{display:inline-flex;border:1px solid #c49d3e;background:#17130a;color:#f2cd68;padding:10px 14px;border-radius:9px}.wf-form{display:grid;gap:14px}.wf-form label{display:grid;gap:7px;color:#aaa}.wf-form input,.wf-form select,.wf-form textarea{width:100%;box-sizing:border-box;background:#090909;color:#eee;border:1px solid #3a3324;border-radius:9px;padding:11px}.wf-step{border:1px solid #332c20;border-radius:12px;padding:16px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.wf-step h3{grid-column:1/-1;margin:0}.wf-timeline{border-left:1px solid #4b3e20;margin-left:8px;padding-left:22px}.wf-event{position:relative;padding:0 0 22px}.wf-event:before{content:'';position:absolute;left:-27px;top:5px;width:9px;height:9px;border-radius:50%;background:#d4af37}.wf-event small{color:#777}@media(max-width:850px){.wf-grid{grid-template-columns:minmax(0,1fr)}.wf-metrics{grid-template-columns:1fr 1fr}}@media(max-width:430px){.wf-hero{align-items:start;flex-direction:column;padding:22px}.wf-metrics{grid-template-columns:1fr}.wf-step{grid-template-columns:1fr}.wf-step h3{grid-column:auto}}
</style>
